  "Dars vaqtida davomatga kiritilmagan": "Während des Unterrichts nicht in die Anwesenheit eingetragen",
  "Bu darsga kirishi uchun kamida {amount} so'm kerak: oy to'lovining {percent}% i to'lanishi shart. Oyni to'liq qoplamasa, qolgan qismi uchun to'lov va'dasi yoziladi.": "Für die Teilnahme an diesem Unterricht sind mindestens {amount} Sum nötig: {percent}% der Monatszahlung müssen bezahlt sein. Wird der Monat nicht vollständig gedeckt, wird für den Rest ein Zahlungsversprechen erfasst.",
  "Bu o'quvchi oy to'lovining kamida {percent}% ini to'lamagan. Shartnomaga ko'ra 2-darsdan boshlab shu qismi to'lanmaguncha darsga qo'yilmaydi. Agar u darsda o'tirsa va keyinroq to'lov qilsa ham, bu dars uchun sizga ish haqi yozilmaydi.": "Dieser Teilnehmer hat nicht die mindestens nötigen {percent}% der Monatszahlung bezahlt. Laut Vertrag wird er ab dem 2. Unterricht nicht zugelassen, bis dieser Teil bezahlt ist. Sitzt er trotzdem im Unterricht und zahlt später, wird Ihnen für diesen Unterricht kein Gehalt gutgeschrieben.",
  "Bu darsga kirishi uchun kamida {amount} so'm kerak. Oyni to'liq qoplamasa, qolgan qismi uchun to'lov va'dasi yoziladi.": "Für die Teilnahme an diesem Unterricht sind mindestens {amount} Sum nötig. Wird der Monat nicht vollständig gedeckt, wird für den Rest ein Zahlungsversprechen erfasst.",
  "Bu o'quvchi oylik to'lovni qilmagan. Shartnomaga ko'ra 2-darsdan boshlab to'lov qilinmaguncha darsga qo'yilmaydi. Agar u darsda o'tirsa va keyinroq to'lov qilsa ham, bu dars uchun sizga ish haqi yozilmaydi.": "Dieser Teilnehmer hat die Monatszahlung nicht geleistet. Laut Vertrag wird er ab dem 2. Unterricht nicht zugelassen, bis er zahlt. Sitzt er trotzdem im Unterricht und zahlt später, wird Ihnen für diesen Unterricht kein Gehalt gutgeschrieben.",

