  // Groups — the lesson changes tab
  "O'chirishda xatolik": "Fehler beim Löschen",
  "Bekor qilingan dars yozuvini o'chirmoqchimisiz?": "Den Eintrag zum abgesagten Unterricht löschen?",
  "Bekor qilishda o'quvchilarga qaytarilgan dars puli ulardan qayta yechiladi; shundan beri muzlatilgan yoki guruhdan chiqqan o'quvchining puli qoladi. Davomat tiklanmaydi. Agar dars vaqti o'tib ketgan bo'lsa, u yana «Dars bo'ldimi?» savoliga qaytadi.": "Das bei der Absage an die Teilnehmer zurückgebuchte Geld für den Unterricht wird ihnen wieder abgebucht; bei einem Teilnehmer, der seitdem eingefroren wurde oder die Gruppe verlassen hat, bleibt das Geld bestehen. Die Anwesenheit wird nicht wiederhergestellt. Ist die Unterrichtszeit bereits vorbei, erscheint der Unterricht wieder bei der Frage „Hat der Unterricht stattgefunden?“.",
  "Bekor qilingan dars yozuvi o'chirildi": "Der Eintrag zum abgesagten Unterricht wurde gelöscht",
  "Bekor qilish o'chirildi: {n} o'quvchidan {amount} so'm qayta yechildi, {kept} o'quvchida qoldi": "Absage gelöscht. Erneut abgebucht: {amount} Sum (Teilnehmer: {n}). Geld blieb bei Teilnehmern: {kept}",
  "Bekor qilish o'chirildi: {n} o'quvchidan {amount} so'm qayta yechildi": "Absage gelöscht. Erneut abgebucht: {amount} Sum (Teilnehmer: {n})",
  "O'rinbosar ustoz qoidasini bekor qilmoqchimisiz?": "Die Vertretungsregelung aufheben?",
  "Oddiy guruh ustozlariga qaytariladi va ularning oyligi qayta hisoblanadi.": "Der Unterricht geht an die regulären Lehrkräfte der Gruppe zurück und deren Gehalt wird neu berechnet.",
  "O'rinbosar bekor qilindi": "Vertretung aufgehoben",
  "Ko'chirish yozuvini o'chirmoqchimisiz?": "Den Verlegungseintrag löschen?",
  "Diqqat: bu ikkala sanada (asl va yangi) davomatni avtomatik tiklamaydi. Agar asl dars vaqti o'tib ketgan bo'lsa, u yana «Dars bo'ldimi?» savoliga qaytadi.": "Achtung: Die Anwesenheit wird an beiden Terminen (ursprünglich und neu) nicht automatisch wiederhergestellt. Ist die ursprüngliche Unterrichtszeit bereits vorbei, erscheint der Unterricht wieder bei der Frage „Hat der Unterricht stattgefunden?“.",
  "Ko'chirish yozuvi o'chirildi": "Der Verlegungseintrag wurde gelöscht",
  "Sana va sababni kiriting": "Geben Sie Datum und Grund ein",
  "Dars bekor qilindi": "Der Unterricht wurde abgesagt",
  "Bekor qilishda xatolik": "Fehler beim Absagen",
  "Agar bu kuni davomat allaqachon olingan bo'lsa, har bir o'quvchining holati \"uzrli sabab bilan kelmadi\" ga o'tadi va undan yechilgan pul qaytariladi (qoldiq darslar hisobi 1 ga oshadi).": "Wurde an diesem Tag bereits Anwesenheit erfasst, wechselt der Status jedes Teilnehmers zu „entschuldigt abwesend“ und das abgebuchte Geld wird zurückgebucht (die Zahl der verbleibenden Unterrichtsstunden steigt um 1).",
  "Bekor qilinadigan dars sanasi": "Datum des abzusagenden Unterrichts",
  "Faqat ushbu guruh dars qiladigan sanalar ko'rinadi": "Es werden nur Tage angezeigt, an denen diese Gruppe Unterricht hat",
  "Ustoz kasal, bayram, va h.k.": "Lehrkraft krank, Feiertag usw.",
  "Kamida 1 ta ustoz bo'lishi kerak": "Es muss mindestens eine Lehrkraft vorhanden sein",
  "O'rinbosar saqlandi": "Vertretung gespeichert",
  "Saqlashda xatolik": "Fehler beim Speichern",
  "Darsga o'rinbosar ustoz tayinlash": "Vertretungslehrkraft für den Unterricht festlegen",
  "Tanlangan kungi dars uchun ustozlarni almashtiring. Agar bu kuni davomat allaqachon olingan bo'lsa, oylik avtomatik qayta hisoblanadi (eski ustozlardan olib tashlanib, yangilarga yoziladi).": "Tauschen Sie die Lehrkräfte für den Unterricht am gewählten Tag aus. Wurde an diesem Tag bereits Anwesenheit erfasst, wird das Gehalt automatisch neu berechnet (bei den bisherigen Lehrkräften abgezogen und den neuen gutgeschrieben).",
  "Dars sanasi": "Unterrichtsdatum",
  "Ushbu guruh dars qiladigan kunlar; ko'chirilgan sanalar ham ro'yxatda chiqadi": "Tage, an denen diese Gruppe Unterricht hat; verlegte Termine erscheinen ebenfalls in der Liste",
  "Bu darsni o'tadigan ustozlar": "Lehrkräfte dieses Unterrichts",
  "Odatda: guruhning {n} ta standart ustozi. Tanlovni o'zgartirsangiz, faqat tanlanganlarga oylik yoziladi.": "Standard: reguläre Lehrkräfte der Gruppe ({n}). Ändern Sie die Auswahl, wird das Gehalt nur den ausgewählten Lehrkräften gutgeschrieben.",
  "Sabab (ixtiyoriy)": "Grund (optional)",
  "Masalan 'Botir kasal'": "Zum Beispiel „Botir ist krank“",
  "Bo'sh xonalarni olishda xatolik": "Fehler beim Abrufen der freien Räume",
  "Asl va yangi sanani tanlang": "Wählen Sie das ursprüngliche und das neue Datum",
  "Yangi sana asl sanadan keyin bo'lishi kerak": "Das neue Datum muss nach dem ursprünglichen liegen",
  "Dars boshlanish vaqtini kiriting": "Geben Sie die Startzeit des Unterrichts ein",
  "Bo'sh xonani tanlang": "Wählen Sie einen freien Raum",
  "Ko'chirilgan dars yangilandi": "Der verlegte Unterricht wurde aktualisiert",
  "Ko'chirishda xatolik": "Fehler beim Verlegen",
  "Ko'chirilgan darsni tahrirlash": "Verlegten Unterricht bearbeiten",
  "Darsni boshqa kunga ko'chirish": "Unterricht auf einen anderen Tag verlegen",
  "Asl sana o'zgartirib bo'lmaydi (audit yozuvi). Yangi sana, vaqt, xona va sababni o'zgartirishingiz mumkin.": "Das ursprüngliche Datum kann nicht geändert werden (Audit-Eintrag). Neues Datum, Uhrzeit, Raum und Grund können Sie ändern.",
  "Bu kungi dars yangi sanaga o'tkaziladi. Asl kunda davomat olingan bo'lsa, to'lov va oylik avtomatik qaytariladi.": "Der Unterricht dieses Tages wird auf das neue Datum verlegt. Wurde am ursprünglichen Tag bereits Anwesenheit erfasst, werden Zahlung und Gehalt automatisch zurückgebucht.",
  "Asl dars sanasi": "Ursprüngliches Unterrichtsdatum",
  "Yangi dars sanasi": "Neues Unterrichtsdatum",
  "Asl sanadan keyingi kun": "Tag nach dem ursprünglichen Datum",
