  "Tanlangan sana va vaqtda bu filialda bo'sh xona yo'q. Vaqtni o'zgartiring yoki boshqa kunni tanlang.": "Am gewählten Datum und zur gewählten Uhrzeit ist in dieser Filiale kein Raum frei. Ändern Sie die Uhrzeit oder wählen Sie einen anderen Tag.",
