  "Tanlangan davrda kamida 10 soniya faol bo'lgan o'quvchilar.": "Teilnehmer, die im gewählten Zeitraum mindestens 10 Sekunden aktiv waren.",
  "O'rtacha faol vaqt": "Durchschnittliche aktive Zeit",
  "kirganlar orasida, bir o'quvchiga": "unter denen, die drin waren, pro Teilnehmer",
  "Faol vaqt: ilova ekranda ochiq va o'quvchi oxirgi 2 daqiqada biror harakat qilgan. Radio bunga kirmaydi.": "Aktive Zeit: Die App ist auf dem Bildschirm geöffnet und der Teilnehmer hat in den letzten 2 Minuten etwas getan. Radio zählt nicht dazu.",
  "birinchi urinishda · {n} savol": "im ersten Versuch · Fragen: {n}",
  "Har bir savol birinchi so'ralganda to'g'ri topilgani. Xatodan keyin qayta so'ralgandagi javob bu foizga kirmaydi.": "Eine Frage zählt, wenn sie beim ersten Stellen richtig beantwortet wurde. Eine Antwort auf die erneut gestellte Frage nach einem Fehler fließt nicht in diesen Prozentsatz ein.",
  "Tugatilgan darslar": "Abgeschlossene Lektionen",
