  "Davrda oxirigacha ishlangan turli darslar. Bitta darsni qayta ishlash qo'shimcha sanalmaydi.": "Verschiedene Lektionen, die im Zeitraum bis zum Ende durchgearbeitet wurden. Dieselbe Lektion erneut zu bearbeiten zählt nicht zusätzlich.",
  "{n} o'quvchi tingladi": "Zugehört: {n}",
  "Ovoz haqiqatan yangragan vaqt. Ekran yopiq bo'lsa ham sanaladi, lekin faol vaqtga qo'shilmaydi.": "Die Zeit, in der der Ton tatsächlich lief. Zählt auch bei ausgeschaltetem Bildschirm, wird aber nicht zur aktiven Zeit addiert.",
  // Groups — app activity table
  "Shug'ullangan kunlar": "Übungstage",
  "Shu kuni kamida bitta mashq qildi yoki kamida 5 daqiqa radio tingladi": "An diesem Tag hat der Teilnehmer mindestens eine Übung gemacht oder mindestens 5 Minuten Radio gehört",
