  // Groups — app activity explainer
  "Raqamlar qanday hisoblanadi": "Wie die Zahlen berechnet werden",
  "ilova ekranda ochiq va o'quvchi oxirgi 2 daqiqada biror harakat qilgan vaqt. Ochiq qoldirilgan tab sanalmaydi.": "die App ist auf dem Bildschirm geöffnet und der Teilnehmer hat in den letzten 2 Minuten etwas getan. Ein offen gelassener Tab zählt nicht.",
  "ovoz haqiqatan yangragan vaqt. Ekran yopiq bo'lsa ham sanaladi, faol vaqtga qo'shilmaydi.": "die Zeit, in der der Ton tatsächlich lief. Zählt auch bei ausgeschaltetem Bildschirm, wird aber nicht zur aktiven Zeit addiert.",
  "kamida bitta mashq javobi yoki kamida 5 daqiqa radio. Faqat ilovani ochish sanalmaydi.": "mindestens eine Antwort in einer Übung oder mindestens 5 Minuten Radio. Die App nur zu öffnen zählt nicht.",
  "Kunlar maxraji": "Nenner der Tage",
  "o'quvchi akkaunti yaratilgan yoki kuzatuv boshlangan kundan sanaladi.": "gezählt ab dem Tag, an dem das Konto des Teilnehmers erstellt oder die Beobachtung begonnen wurde.",
  "Kuzatuv {date} dan boshlangan.": "Die Beobachtung begann am {date}.",
  "har bir savol birinchi so'ralganda to'g'ri topilgani. Xatodan keyin qayta so'ralgandagi javob bu foizga kirmaydi. O'quvchi natija ekranida ko'radigan raqam bilan bir xil ta'rif.": "jede Frage zählt, wenn sie beim ersten Stellen richtig beantwortet wurde. Eine Antwort auf die erneut gestellte Frage nach einem Fehler fließt nicht in diesen Prozentsatz ein. Dieselbe Definition wie bei der Zahl auf dem Ergebnisbildschirm des Teilnehmers.",
  "darajadagi kurs darslaridan tugatilganlari; o'quvchi darajasi guruhnikidan past bo'lsa «Guruhdan orqada» belgisi.": "abgeschlossene Kurslektionen auf diesem Niveau; liegt das Niveau des Teilnehmers unter dem der Gruppe, erscheint die Markierung «Hinter der Gruppe».",
