  "Guruh faol emas ({status}). Davomat olish mumkin emas.": "Die Gruppe ist nicht aktiv ({status}). Anwesenheit kann nicht erfasst werden.",
  "Dars {start} da boshlanadi (Toshkent vaqti). Davomat dars boshlanishidan {n} daqiqa oldin ochiladi": "Der Unterricht beginnt um {start} (Taschkenter Zeit). Die Anwesenheitserfassung öffnet {n} Min. vor Beginn",
  "Dars vaqti tugagan ({start} – {end}, Toshkent vaqti). Davomat olish yopilgan": "Die Unterrichtszeit ist vorbei ({start} – {end}, Taschkenter Zeit). Die Anwesenheitserfassung ist geschlossen",
  "Dars davom etmoqda ({start} – {end}, Toshkent vaqti)": "Der Unterricht läuft ({start} – {end}, Taschkenter Zeit)",
  "To'lov qabul qilindi, lekin ro'yxatni yangilab bo'lmadi. Sahifani qayta yuklang": "Zahlung angenommen, aber die Liste konnte nicht aktualisiert werden. Laden Sie die Seite neu",
  "Oldindan belgilandi": "Im Voraus markiert",
  "Oldindan belgilash o'chirildi": "Vorabmarkierung entfernt",
  "Barcha o'quvchilarning holati belgilanishi shart. Belgilanmagan: {n} ta": "Alle Teilnehmer müssen markiert werden. Nicht markiert: {n}",
  "Davomat muvaffaqiyatli saqlandi": "Anwesenheit gespeichert",
  "Orqaga": "Zurück",
  "Davomat olib bo'lingan. Tahrirlash uchun administratorga murojaat qiling": "Die Anwesenheit ist bereits erfasst. Wenden Sie sich zum Bearbeiten an die Verwaltung",
  "Dars tugagan — davomat olish yopilgan. Dars bo'lgan-bo'lmaganini «Davomat olinmagan darslar» ro'yxatida, «Jadval» yoki «Topshiriqlar»da belgilang.": "Der Unterricht ist vorbei — die Anwesenheitserfassung ist geschlossen. Ob der Unterricht stattfand, markieren Sie in der Liste «Unterricht ohne Anwesenheitserfassung», im «Stundenplan» oder unter «Aufgaben».",
  "Oldindan belgilash rejimi — bugun kelmaydigan o'quvchini hozir belgilang. Dars vaqtida ustoz davomatni oladi; belgilangan o'quvchilar \"Sababli\" bo'lib turadi (pul yechilmaydi).": "Vorabmarkierung — markieren Sie jetzt, wer heute nicht kommt. Im Unterricht erfasst die Lehrkraft die Anwesenheit; markierte Teilnehmer bleiben „Entschuldigt“ (es wird kein Geld abgebucht).",
