  "Bu o'quvchilar oylik to'lovni to'liq to'lamagan. «Shu oy» ustuni to'lov oyning nechta darsiga yetishini ko'rsatadi.": "Diese Teilnehmer haben die Monatszahlung nicht vollständig bezahlt. Die Spalte «Dieser Monat» zeigt, für wie viele Unterrichtsstunden des Monats die Zahlung reicht.",
  "Bu o'quvchilarning balansi manfiyga tushgan. Davomat olinishi davom etadi va har bir dars bahosi balansdan ushlanmoqda — to'lov qabul qilingach, ustozning oyligiga ham hisoblanadi.": "Der Kontostand dieser Teilnehmer ist negativ. Die Anwesenheit wird weiter erfasst und der Preis jeder Unterrichtsstunde vom Kontostand abgebucht — nach der Zahlung wird er auch dem Gehalt der Lehrkraft angerechnet.",
