  "\"{name}\" arxivga o'tkaziladi. Keyinchalik arxivdan tiklash mumkin.": "„{name}“ wird archiviert. Später kann die Lehrkraft aus dem Archiv wiederhergestellt werden.",
  "Ko'rsatkichlar": "Kennzahlen",
  "Taymlayn": "Zeitachse",
  "Baholar": "Bewertungen",
  "Tarix ma'lumotlari mavjud emas": "Keine Verlaufsdaten vorhanden",
  "Guruhlar hali ulanmagan": "Noch keine Gruppen zugeordnet",
  "{n} nafar": "{n} Pers.",
  "Ko'rsatkichlarni yuklab bo'lmadi. Sahifani yangilang.": "Die Kennzahlen konnten nicht geladen werden. Laden Sie die Seite neu.",
  "Oylik dinamikasi": "Gehaltsentwicklung",
  "{month}: {amount}": "{month}: {amount}",
  "{month} (davom etmoqda): {amount}": "{month} (laufend): {amount}",
  "Har oy to'liq ishlangan pul — «Ish haqi» bo'limidagi raqamning o'zi.\nJoriy oy hali tugamagan: raqam oy oxirigacha o'sadi.": "Pro Monat voll verdientes Geld – dieselbe Zahl wie im Bereich «Gehalt».\nDer aktuelle Monat ist noch nicht zu Ende: Die Zahl steigt bis zum Monatsende.",
  "Bu oylarda oylik yo'q": "In diesen Monaten gibt es kein Gehalt",
  "Oylik": "Gehalt",
  "Hozir: {n} nafar": "Aktuell: {n} Pers.",
  "Har oy oxirida ustoz guruhlarida o'qiyotgan o'quvchilar soni.\nGuruh boshqa ustozga o'tgan oydan boshlab sanalmaydi.": "Anzahl der Teilnehmer, die am Ende jedes Monats in den Gruppen der Lehrkraft lernen.\nAb dem Monat, in dem die Gruppe an eine andere Lehrkraft übergeht, werden sie nicht mehr gezählt.",
  "Kelganlar va ketganlar": "Zugänge und Abgänge",
  "{month}: +{joined} qo'shildi, −{left} ketdi": "{month}: +{joined} hinzugekommen, −{left} ausgetreten",
  "Yashil — ustoz guruhiga qo'shilganlar (boshqa guruhdan o'tganlar ham).\nQizil — markazdan ketganlar («Ketganlar» hisobotidagi qoida).\nOch qizil — to'xtagan, lekin hali qaytishi mumkin (21 kun, muzlatishda 60 kun).": "Grün – der Gruppe der Lehrkraft beigetreten (auch aus einer anderen Gruppe gewechselt).\nRot – aus dem Zentrum ausgetreten (Regel des Berichts «Ausgetreten»).\nHellrot – nicht mehr erschienen, könnten aber noch zurückkehren (21 Tage, bei Pausierung 60 Tage).",
  "Bu oylarda kelgan ham, ketgan ham yo'q": "In diesen Monaten gab es weder Zu- noch Abgänge",
  "Qaytishi mumkin": "Könnten zurückkehren",
  "{month}: {pct}%": "{month}: {pct}%",
  "Kelgan va kechikkanlar ÷ (kelgan + kechikkan + kelmagan).\nSababli va bekor qilingan darslar hisobga olinmaydi.": "Anwesende und Verspätete ÷ (anwesend + verspätet + abwesend).\nEntschuldigte und abgesagte Unterrichtsstunden werden nicht berücksichtigt.",
  "Bu oylarda davomat olinmagan": "In diesen Monaten wurde keine Anwesenheit erfasst",
  "Hech qanday muhim o'zgarish topilmadi": "Keine wesentlichen Änderungen gefunden",
  "{month} — bu oy qo'lda kiritilgan, har bir dars bo'yicha ma'lumot yo'q. Faqat kiritilgan summa va avans ko'rsatilgan.": "{month} – dieser Monat wurde manuell erfasst, es gibt keine Angaben zu den einzelnen Unterrichtsstunden. Angezeigt werden nur der erfasste Betrag und der Vorschuss.",
  "{month} uchun oylik ma'lumoti yo'q — boshqa oyni tanlab ko'ring.": "Keine Gehaltsdaten für {month} – wählen Sie einen anderen Monat.",
  "To'lanishi kerak": "Auszuzahlen",
  "Bu oy uchun to'lanishi kerak bo'lgan sof summa: to'liq ishlangan (markaz qo'shimchasi bilan) − avans. Hisoblab bo'lingan oylar uchun haqiqiy to'langan summa ko'rsatiladi.": "Nettobetrag, der für diesen Monat auszuzahlen ist: voll verdient (mit Zuschuss des Zentrums) − Vorschuss. Für bereits berechnete Monate wird der tatsächlich gezahlte Betrag angezeigt.",
  "Oylik (belgilangan)": "Gehalt (festgelegt)",
  "Avans": "Vorschuss",
  "To'liq ishlangan": "Voll verdient",
  "O'quvchilar to'lagan": "Von Teilnehmern bezahlt",
  "To'liq ishlangandan o'quvchilar haqiqatan to'lagani bilan qoplangan qismi.": "Der Teil des voll verdienten Betrags, der durch die tatsächlichen Zahlungen der Teilnehmer gedeckt ist.",
  "Markaz qo'shimchasi": "Zuschuss des Zentrums",
  "Markazning o'z hisobidan qo'shgan (yoki oy yopilgunicha qo'shadigan) qismi. Oy yopilgach bu raqam qolaveradi — o'quvchi keyin to'lasa, pul markazga qaytadi, ustozga qayta yozilmaydi. Oylik to'lov kurslarida o'quvchi hali to'lamagan oylik hisobining ulushi ham shu yerda — u to'lagan sari kamayadi.": "Der Teil, den das Zentrum aus eigenen Mitteln zugeschossen hat (oder bis zum Monatsabschluss zuschießt). Nach dem Monatsabschluss bleibt diese Zahl bestehen: Zahlt der Teilnehmer später, geht das Geld ans Zentrum zurück und wird der Lehrkraft nicht erneut gutgeschrieben. Bei Kursen mit Monatszahlung ist hier auch der Anteil der noch nicht bezahlten Monatsabrechnung enthalten – er sinkt, je mehr der Teilnehmer zahlt.",
  "Shu oy ichida ustozga oldindan berilgan pul (Xarajatlar → Avans). U «To'lanishi kerak»dan allaqachon ayirilgan.": "Im Laufe dieses Monats vorab an die Lehrkraft ausgezahltes Geld (Ausgaben → Vorschuss). Es ist bereits von «Auszuzahlen» abgezogen.",
  "Shu oy uchun to'lanishi kerak bo'lgan sof summa — avans allaqachon ayirilgan. «Ish haqi» bo'limidagi va Moliya → Oyliklar sahifasidagi raqam bilan bir xil.": "Nettobetrag, der für diesen Monat auszuzahlen ist – der Vorschuss ist bereits abgezogen. Entspricht der Zahl im Bereich «Gehalt» und auf der Seite Finanzen → Gehälter.",
  "Ishlangan {amount}": "Verdient {amount}",
  "avans −{amount}": "Vorschuss −{amount}",
  "Eslatma — bu summalardan ushlanishi mumkin:": "Hinweis – von diesen Beträgen können abgezogen werden:",
  "Ustoz oyligidan — 12%": "Vom Gehalt der Lehrkraft – 12%",
  "Markaz tomonidan ustoz oyligiga — 12%": "Vom Zentrum auf das Gehalt der Lehrkraft – 12%",
