  "Dars tugaguncha davomat olinmagan. Bu darslar uchun ish haqi yozilmaydi: summa — o'sha kuni to'lagan o'quvchilar bo'yicha ustoz ulushi.": "Die Anwesenheit wurde bis zum Unterrichtsende nicht erfasst. Für diesen Unterricht wird kein Gehalt gutgeschrieben: Der Betrag ist der Anteil der Lehrkraft an den Teilnehmern, die an diesem Tag bezahlt haben.",
