  "O'quvchi 2+ guruhda — qaysi sikl uchun yechilishini sistema avtomatik tanlaydi.": "Der Teilnehmer ist in 2+ Gruppen — das System wählt automatisch, für welchen Zyklus abgebucht wird.",
