  "Qarz to'liq yopiladi: oyning oxirigacha qatnashadi.": "Die Schulden werden vollständig beglichen: Teilnahme bis zum Monatsende.",
  "Bu pul darsga kirish uchun yetmaydi: oy to'lovining kamida {percent}% i to'lanishi kerak — yana {amount} so'm ({date}, {group}).": "Dieses Geld reicht nicht für die Teilnahme am Unterricht: mindestens {percent}% der Monatszahlung müssen bezahlt sein — noch {amount} Sum ({date}, {group}).",
  "Bu pul bugungi darsga yetmaydi: kamida yana {amount} so'm kerak ({date}, {group}).": "Dieses Geld reicht nicht für den heutigen Unterricht: mindestens {amount} Sum mehr nötig ({date}, {group}).",
  "Bu pul {date} gacha yetadi: bugungi darsga kiradi.": "Dieses Geld reicht bis {date}: Teilnahme am heutigen Unterricht.",
  "Keyingi dars {date} ({group}): oy to'lovining kamida {percent}% i to'lanishi kerak — yana {amount} so'm.": "Nächster Unterricht {date} ({group}): mindestens {percent}% der Monatszahlung müssen bezahlt sein — noch {amount} Sum.",
