  "Shu oy guruhdan chiqqanlarning shu oy qarzi — {amount} — «O'qimayotganlar» bo'limida.": "Die Schulden dieses Monats derer, die in diesem Monat ihre Gruppe verlassen haben — {amount} — stehen im Bereich «Nicht mehr lernend».",
  "O'quvchi ustiga bosing — qarz tafsiloti, aloqa va va'da o'ng tomonda ochiladi": "Klicken Sie auf einen Teilnehmer — Schuldendetails, Kontakt und Zahlungsversprechen öffnen sich rechts",
