  "{month} to'lovini hali to'liq to'lamagan o'qiyotgan o'quvchilar. To'lov muddati — shartnoma bo'yicha oyning 2-darsigacha.": "Lernende Teilnehmer, die die Zahlung für {month} noch nicht vollständig geleistet haben. Zahlungsfrist laut Vertrag: bis zur 2. Unterrichtsstunde des Monats.",
  "O'qiyotgan, lekin o'tgan oylardan qarzi qolgan o'quvchilar. Shartnomaga ko'ra 2-darsga kirish uchun eski qarz ham to'lanishi kerak.": "Lernende Teilnehmer mit Schulden aus früheren Monaten. Laut Vertrag müssen für die Teilnahme an der 2. Unterrichtsstunde auch alte Schulden bezahlt werden.",
  "Hozir hech qaysi guruhda o'qimayotganlar: guruhsiz qolgan, muzlatilgan yoki ketgan. Bu — undirish ro'yxati: qo'ng'iroq, va'da, to'lov.": "Derzeit in keiner Gruppe: ohne Gruppe, eingefroren oder ausgetreten. Dies ist die Inkasso-Liste: Anruf, Zahlungsversprechen, Zahlung.",
