  "Barcha qarzdorlar — hozir o'qiyotgani ham, ketgani ham.": "Alle Schuldner — aktuell lernende wie ausgetretene.",
  "Qarz oyma-oy qanday o'zgargan: qancha qo'shilgan, qanchasi to'langan va oy oxirida qancha qolgan.": "Wie sich die Schulden Monat für Monat verändert haben: wie viel hinzukam, wie viel bezahlt wurde und wie viel am Monatsende offen blieb.",
  "Butun kompaniya bo'yicha — bu jadval filialga bo'linmaydi.": "Für das gesamte Unternehmen — diese Tabelle wird nicht nach Filialen aufgeteilt.",
  "O'quvchi o'qishni tashlagani uchun undirilmaydigan deb belgilangan qarzlar.": "Schulden, die als nicht eintreibbar markiert wurden, weil der Teilnehmer den Unterricht abgebrochen hat.",
  "Markaz o'quvchilar to'lamagan darslar uchun ustozlarga pul to'lab bergan. Bu yerda o'sha pul kimdan undirilishi kerakligi ko'rinadi.": "Das Zentrum hat Lehrkräften Unterricht bezahlt, den Teilnehmer nicht bezahlt haben. Hier sieht man, von wem dieses Geld einzutreiben ist.",
  "Davr tanlovi qaysi oydagi darslar hisobga olinishini belgilaydi — o'quvchining qarz summasi o'zgarmaydi.": "Die Zeitraumauswahl bestimmt, welche Monate des Unterrichts gezählt werden — die Schuldsumme des Teilnehmers ändert sich nicht.",
  "Butun davr": "Gesamter Zeitraum",
  "Markaz qoplagan, hali qaytmagan dars yo'q — hammasi undirilgan.": "Kein vom Zentrum gedeckter, noch offener Unterricht — alles eingetrieben.",
  "{month}da markaz qoplagan dars yo'q — bu oyda hali dars o'tilmagan yoki hamma o'quvchi to'lagan.": "Im {month} gibt es keinen vom Zentrum gedeckten Unterricht — in diesem Monat fand noch kein Unterricht statt oder alle Teilnehmer haben bezahlt.",
