  "Darsga kelmaydi — pul o'zi qaytmaydi": "Kommen nicht zum Unterricht — das Geld kommt nicht von selbst zurück",
  "{month} oyligi hali yopilmagan.": "Das Gehalt für {month} ist noch nicht abgeschlossen.",
  "Darslar o'tilgan, lekin markaz ustozlarga hali to'lagani yo'q — bu pul oy yopilganda chiqadi. Ya'ni hozir undirilsa, markaz umuman to'lamaydi.": "Der Unterricht hat stattgefunden, aber das Zentrum hat die Lehrkräfte noch nicht bezahlt — dieses Geld geht bei Monatsabschluss raus. Wird jetzt eingetrieben, zahlt das Zentrum also gar nicht.",
  "filtrlangan": "gefiltert",
  "«Markaz hali olmagan» — jami qarzning markaz ustozlarga chiqarib bo'lgan qismi. «Jami qarzi» esa o'quvchining profilidagi to'liq qarzi: unga markaz qoplamagan oldingi oylar ham kiradi, qaysilari ekani «⧉» nishonida.": "«Zentrum noch nicht erhalten» ist der Teil der Gesamtschuld, den das Zentrum bereits an Lehrkräfte ausgezahlt hat. «Gesamtschuld» ist die volle Schuld aus dem Teilnehmerprofil: Sie umfasst auch frühere, nicht vom Zentrum gedeckte Monate; welche, zeigt das Symbol «⧉».",
  "Oylik sahifasidagi kartada {amount} turibdi — farqi puli to'liq qaytgan {n} o'quvchi, ular bu ro'yxatda ko'rinmaydi.": "Auf der Karte der Gehaltsseite stehen {amount} — die Differenz sind Teilnehmer, deren Geld vollständig zurückgeflossen ist (Teilnehmer: {n}); sie erscheinen nicht in dieser Liste.",
  "{n} ta o'quvchi faol emas (muzlatilgan / chetlatilgan / arxiv). Ular darsga kelmaydi, ya'ni bu pul o'z-o'zidan qaytmaydi — ular bilan bog'lanish kerak.": "Nicht aktive Teilnehmer: {n} (eingefroren / ausgeschlossen / archiviert). Sie kommen nicht zum Unterricht, das Geld kommt also nicht von selbst zurück — sie müssen kontaktiert werden.",
  "Ism, telefon yoki ID bo'yicha qidirish…": "Nach Name, Telefon oder ID suchen…",
  "Ro'yxat ichidan qidirish": "In der Liste suchen",
  "Qoplanadigan oylar": "Zu deckende Monate",
  "Markaz qoplagan oylar": "Vom Zentrum gedeckte Monate",
  "Markaz hali olmagan": "Zentrum noch nicht erhalten",
  "«{query}» bo'yicha hech kim topilmadi.": "Zu «{query}» wurde niemand gefunden.",
  "Bu holatda o'quvchi yo'q — filtrni o'zgartirib ko'ring.": "Keine Teilnehmer mit diesem Status — ändern Sie den Filter.",
  "{month}: {n} dars": "{month} — Unterrichtsstunden: {n}",
  "Jami {n} ta": "Gesamt: {n}",
  "Kechirish qaytarib olindi — o'quvchi yana qarzdor": "Erlass zurückgenommen — der Teilnehmer ist wieder Schuldner",
  "Qaytarib olishda xatolik yuz berdi": "Erlass konnte nicht zurückgenommen werden",
  "Qaysi kundan": "Ab welchem Tag",
  "Qaysi kungacha": "Bis zu welchem Tag",
