  "Muzlatilganiga necha kun bo'lgan": "Seit wie vielen Tagen eingefroren",
  "O'quvchini qidirish": "Teilnehmer suchen",
  "O'quvchi ustiga bosing — tafsilot va amallar o'ng tomonda ochiladi": "Klicken Sie auf einen Teilnehmer – Details und Aktionen öffnen sich rechts",
  "Ro'yxatni yuklab bo'lmadi.": "Die Liste konnte nicht geladen werden.",
