  "Pul oyning qolgan darslari hisobiga o'tadi.": "Das Geld wird auf die restlichen Unterrichtsstunden des Monats angerechnet.",
  "Guruhga qaytarish": "In die Gruppe zurückführen",
  "Pul shu oyning qolgan darslari hisobiga o'tadi.": "Das Geld wird auf die restlichen Unterrichtsstunden dieses Monats angerechnet.",
  "Guruh tanlash": "Gruppe wählen",
  "Pulni o'quvchiga qaytarish": "Geld an den Teilnehmer zurückzahlen",
  "So'rov ochiladi: balans 0 bo'ladi, pul 10 bank kuni ichida beriladi.": "Es wird ein Antrag eröffnet: Das Guthaben wird 0, das Geld wird innerhalb von 10 Bankarbeitstagen ausgezahlt.",
  "Qaytarishni boshlash": "Rückzahlung starten",
  "Markaz hisobiga o'tkazish": "Auf das Konto des Zentrums übertragen",
  "Pul markaz daromadiga o'tadi. Sabab yoziladi.": "Das Geld wird zur Einnahme des Zentrums. Der Grund wird festgehalten.",
  "O'tkazish": "Übertragen",
  "Xabar botga yuborildi": "Nachricht über den Bot gesendet",
  "Qo'ng'iroq belgilandi": "Anruf vermerkt",
  "Xabarni saqlashda xatolik": "Die Benachrichtigung konnte nicht gespeichert werden",
  "Xabar berish": "Benachrichtigen",
  "«Pulingizni olib keting» — markazga o'tkazishdan oldin kamida bir marta.": "«Holen Sie Ihr Geld ab» – mindestens einmal vor der Übertragung an das Zentrum.",
  "Bot ulanmagan — qo'ng'iroq qiling va belgilang.": "Bot nicht verbunden – rufen Sie an und vermerken Sie es.",
  "Filial telefon raqami kiritilmagan": "Die Telefonnummer der Filiale ist nicht eingetragen",
  "Pul berildi": "Geld ausgezahlt",
  "{name} · so'rov {requested} · muddat {due}": "{name} · Antrag {requested} · Frist {due}",
  "Berilgan summa": "Ausgezahlter Betrag",
  "Qaysi kassadan": "Aus welcher Kasse",
  "O'quvchining filialida kassa topilmadi": "In der Filiale des Teilnehmers wurde keine Kasse gefunden",
  "Kassani tanlang": "Kasse wählen",
  "Kassa qoldig'idan shu summa ayiriladi va kvitansiya chiqadi. Sana — bugun.": "Der Betrag wird vom Kassenbestand abgezogen und eine Quittung erstellt. Datum: heute.",
  "So'rov bekor qilindi — pul balansga qaytdi": "Antrag abgebrochen – das Geld ist zurück auf dem Guthaben",
  "So'rovni bekor qilishda xatolik yuz berdi": "Der Abbruch ist fehlgeschlagen",
  "Masalan: o'quvchi guruhga qaytdi": "Zum Beispiel: Teilnehmer ist in die Gruppe zurückgekehrt",
  "bekor qilindi": "abgebrochen",
  "Qaytarishlar tarixi": "Rückzahlungsverlauf",
  "Berilgan va bekor qilingan so'rovlar": "Ausgezahlte und abgebrochene Anträge",
  "Tarixni yuklab bo'lmadi.": "Der Verlauf konnte nicht geladen werden.",
  "Hali berilgan yoki bekor qilingan so'rov yo'q": "Noch keine ausgezahlten oder abgebrochenen Anträge",
  "Kim berdi / Kim bekor qildi": "Wer ausgezahlt / Wer abgebrochen hat",
  // Payments — «Ish haqi» page, table, drawer, pay dialog, advances
  "Xodim": "Mitarbeiter",
  "Stavkalar": "Vergütungssätze",
  "Avans berish": "Vorschuss auszahlen",
  "Avanslar": "Vorschüsse",
  "Markaz qoplagani": "Vom Zentrum gedeckt",
  "Ism yoki ID": "Name oder ID",
  "Jadvalda «O'quvchilar to'lagan / Markaz qo'shdi» ustunlari yo'q — ular xodim oynasida. «Avans» — aynan shu oylikdan ushlanadigan summa. Hisoblash davri doim kalendar oyi (1-sanadan).": "Die Tabelle hat keine Spalten «Von Teilnehmern bezahlt / Zuschuss des Zentrums» — sie stehen im Mitarbeiterfenster. «Vorschuss» ist der Betrag, der genau von diesem Gehalt abgezogen wird. Der Abrechnungszeitraum ist immer der Kalendermonat (ab dem 1.).",
  "Ishdan bo'shagan. Ro'yxatda turibdi, chunki bu oyning puli hali yopilmagan — yopilgach o'zi tushib qoladi.": "Ausgeschieden. Bleibt in der Liste, weil das Geld dieses Monats noch nicht abgeschlossen ist — danach verschwindet der Eintrag von selbst.",
  "Jami avans": "Vorschüsse gesamt",
  "Berilgan kunlar": "Auszahlungstage",
  "{n} kun": "{n} Tg.",
  "Eng katta kun": "Größter Tag",
  "Bu oyda avans berilmagan — «Avans berish» tugmasi bilan qo'shing.": "In diesem Monat wurde kein Vorschuss ausgezahlt — mit «Vorschuss auszahlen» hinzufügen.",
  "Bu oyda avans berilmagan.": "In diesem Monat wurde kein Vorschuss ausgezahlt.",
  "{n} ta avans ({amount}) oyligi belgilanmagan xodimga berilgan — oylik belgilanmaguncha hech qaysi oylikdan ushlanmaydi va «Oyliklar» tabida ko'rinmaydi.": "Vorschüsse: {n} ({amount}) — an Mitarbeiter ohne festgelegtes Gehalt ausgezahlt; bis ein Gehalt festgelegt ist, werden sie von keinem Gehalt abgezogen und erscheinen nicht im Tab «Gehälter».",
  "{day}-kun, {amount} so'm avans": "{day}. Tag, Vorschuss {amount} Sum",
  "{day}-kun, avans yo'q": "{day}. Tag, kein Vorschuss",
  "Tafsilotni ko'rish uchun kalendardan kun tanlang.": "Wählen Sie einen Tag im Kalender, um Details zu sehen.",
  "Jami {amount} · {n} ta": "Gesamt {amount} · Vorschüsse: {n}",
  "Bu kunda avans berilmagan.": "An diesem Tag wurde kein Vorschuss ausgezahlt.",
  "{name} bergan": "ausgezahlt von {name}",
  "Bu kunga avans qo'shish": "Vorschuss für diesen Tag hinzufügen",
  "Avans yangilandi": "Vorschuss aktualisiert",
  "Avans qo'shildi": "Vorschuss hinzugefügt",
  "Avansni saqlashda xatolik": "Fehler beim Speichern des Vorschusses",
  "Avansni tahrirlash": "Vorschuss bearbeiten",
  "Avans qo'shish": "Vorschuss hinzufügen",
  "Xodim o'zgarmaydi. Avans boshqa odamga yozilgan bo'lsa — buni o'chirib, to'g'ri xodimga yangi avans yozing.": "Der Mitarbeiter lässt sich nicht ändern. Wurde der Vorschuss der falschen Person zugeordnet, löschen Sie ihn und erfassen Sie einen neuen für den richtigen Mitarbeiter.",
  "Avans keyingi oylik hisobida ushbu xodimning oyligidan avtomatik ushlab qolinadi": "Der Vorschuss wird bei der nächsten Gehaltsabrechnung automatisch vom Gehalt dieses Mitarbeiters abgezogen",
  "Avans haqida...": "Zum Vorschuss...",
  "Sana o'zgarsa avans hisobotlarda yangi kunga ko'chadi, Kassa oqimidagi harakat esa kiritilgan kunida qoladi.": "Ändert sich das Datum, rückt der Vorschuss in den Berichten auf den neuen Tag, die Buchung im Kassenfluss bleibt am Erfassungstag.",
  "Avans o'chirildi": "Vorschuss gelöscht",
  "Avansni o'chirasizmi?": "Vorschuss löschen?",
  "{name} — {amount} so'm, {date}. Pul kassaga qaytariladi va bu avans keyingi oylik hisobiga tushmaydi. Bu amalni qaytarib bo'lmaydi.": "{name} — {amount} Sum, {date}. Das Geld geht in die Kasse zurück, und dieser Vorschuss fließt nicht in die nächste Gehaltsabrechnung ein. Dies kann nicht rückgängig gemacht werden.",
