  "Eng pastdan tartiblangan. Ro'yxatda yo'q qatorlar ham umumiy foizga kiradi, shuning uchun kesimlar yig'indisi umumiy sonlarga teng.": "Vom niedrigsten Wert an sortiert. Zeilen, die nicht in der Liste stehen, zählen ebenfalls zum Gesamtprozentwert, daher ergibt die Summe der Aufschlüsselungen die Gesamtzahlen.",
