  "{n} o'quvchi 3 va undan ko'p darsga ketma-ket sababsiz kelmadi.": "Teilnehmer, die 3 oder mehr Unterrichtsstunden in Folge unentschuldigt gefehlt haben: {n}.",
  "Ko'p qoldiruvchilar — {name}": "Häufig Abwesende — {name}",
  "Tanlangan davrda 3 va undan ko'p marta «Kelmadi» belgilangan o'quvchilar.": "Teilnehmer, die im gewählten Zeitraum 3-mal oder öfter als «Abwesend» markiert wurden.",
