  "Bu bugungi holat, tanlangan davrga bog'liq emas. Hisob biroz farq qiladi: oldindan aytilgan sababsiz yo'qlik kelmagan hisoblanadi, markaz bekor qilgan darslar ko'rinmaydi, faqat faol o'quvchilar sanaladi.": "Das ist der heutige Stand, unabhängig vom gewählten Zeitraum. Die Zählung weicht etwas ab: Eine vorher angekündigte unentschuldigte Abwesenheit gilt als Fehlen, vom Zentrum abgesagte Unterrichtsstunden sind nicht sichtbar, nur aktive Teilnehmer werden gezählt.",
