  "oyda xodimga kelgan lidlar (o'zi band qilgan yoki unga berilgan, har lid bir marta) dan nechtasida uning «Lid to'lov qildi» natijasi bor. Joriy oyda hali to'lamaganlar ham hisobda.": "wie viele der Leads, die der Mitarbeiter im Monat erhielt (selbst übernommen oder ihm zugewiesen, jeder Lead einmal), sein Ergebnis „Lead hat bezahlt“ haben. Im laufenden Monat zählen auch die mit, die noch nicht bezahlt haben.",
  "Va'da bajarilishi": "Einhaltungsquote der Versprechen",
  "xodim yozgan, va'da kuni shu oyga tushgan va'dalardan bajarilganlari: bajarilgan / (bajarilgan + buzilgan). Ochiq va'da kirmaydi.": "Anteil der eingehaltenen unter den vom Mitarbeiter erfassten Versprechen, deren Termin in diesen Monat fällt: eingehalten / (eingehalten + gebrochen). Offene Versprechen zählen nicht.",
