  "«Butun markaz» — hamma filialda dam olish kuni. Filial tanlansa, bayram faqat o'sha filial guruhlariga tegadi.": "„Gesamtes Zentrum“ — freier Tag in allen Filialen. Wird eine Filiale gewählt, betrifft der Feiertag nur die Gruppen dieser Filiale.",
