  "Yangi chiqish sababi": "Neuer Austrittsgrund",
  "O'quvchi ustozi boshqa bo'lgan guruhga o'tkazilganda sabab tanlash majburiy. Bu ro'yxat bo'sh bo'lsa o'tkazish umuman bajarilmaydi.": "Wird ein Teilnehmer in eine Gruppe mit einer anderen Lehrkraft übertragen, ist ein Grund Pflicht. Ist diese Liste leer, wird die Übertragung gar nicht ausgeführt.",
