  "Bir kunda belgilangandan ko'p nomzod chiqsa, hech kim pauzalanmaydi va sizga xabar keladi.": "Gibt es an einem Tag mehr Kandidaten als festgelegt, wird niemand pausiert und Sie erhalten eine Benachrichtigung.",
  "Pauzadagilarni ko'rish": "Pausierte ansehen",
  "O'zgarish tarixi": "Änderungsverlauf",
  "Avtomatik pauza sozlamasini kim va qachon o'zgartirgan": "Wer die automatische Pause wann geändert hat",
  "Hali o'zgarish yo'q. Sozlama saqlangach, shu yerda ko'rinadi.": "Noch keine Änderungen. Sobald die Einstellung gespeichert ist, erscheinen sie hier.",
  "Qiymatni kiriting": "Geben Sie einen Wert ein",
  "{min} dan {max} gacha bo'lishi kerak": "Muss zwischen {min} und {max} liegen",
  "Xabar chegarasi pauza chegarasidan kichik bo'lishi kerak": "Der Grenzwert für die Nachricht muss kleiner sein als der für die Pause",
  "O'quvchi ketma-ket {warn} ta dars qoldirsa xabar oladi, {pause} ta qoldirsa pauzaga o'tadi.": "Fehlstunden in Folge: {warn} — der Teilnehmer erhält eine Nachricht, {pause} — er wird pausiert.",
  "Hozir {pause} va undan ko'p dars qoldirgan o'quvchi yo'q.": "Derzeit hat niemand {pause} oder mehr Unterrichtsstunden in Folge gefehlt.",
  "Hozir {n} nafar o'quvchi {pause} va undan ko'p dars qoldirgan. Bu kunlik chegaradan ({cap}) ko'p — hech kim pauzalanmaydi, sizga xabar keladi.": "Teilnehmer mit {pause} oder mehr Fehlstunden in Folge: {n}. Das ist mehr als das Tageslimit ({cap}) — niemand wird pausiert, Sie erhalten eine Benachrichtigung.",
  "Hozir {n} nafar o'quvchi {pause} va undan ko'p dars qoldirgan. Saqlasangiz, navbatdagi 07:30 yurishda ular pauzaga o'tadi.": "Teilnehmer mit {pause} oder mehr Fehlstunden in Folge: {n}. Wenn Sie speichern, werden sie beim nächsten Lauf um 07:30 pausiert.",
  "Xabar chegarasi": "Grenzwert Nachricht",
  "Pauza chegarasi": "Grenzwert Pause",
  "Kunlik chegara": "Tageslimit",
