  "O'quvchi guruh ro'yxatiga qaytadi va darslari uchun yana hisob yozila boshlaydi. Ketma-ket qoldirish sanog'i noldan boshlanadi — ya'ni u yana chegaracha dars imkoniyati oladi.": "Der Teilnehmer kehrt in die Gruppenliste zurück, und für seinen Unterricht wird wieder abgerechnet. Der Zähler für Fehlstunden in Folge beginnt bei null — er hat also wieder so viele Unterrichtsstunden bis zur Grenze.",
