  "Masalan: Hören": "Zum Beispiel: Hören",
  "Kamida 1 ta bo'lim qoldirish kerak": "Mindestens ein Teil muss bleiben",
  "Bo'lim qo'shish": "Teil hinzufügen",
  "Goethe B1+ modular formati: har bo'lim 100 dan, o'tish 60. O'tish balli ixtiyoriy.": "Modulares Format Goethe B1+: jeder Teil 100 Punkte, bestanden ab 60. Die Mindestpunktzahl ist optional.",
  "Bu imtihon bepul bo'ladimi?": "Ist diese Prüfung kostenlos?",
  "Narx kiritilmadi. Agar shunday davom etsangiz, imtihon bepul bo'lib yaratiladi va bot ro'yxatdan o'tganlardan to'lov so'ramaydi.": "Es wurde kein Preis eingegeben. Wenn Sie fortfahren, wird die Prüfung kostenlos erstellt und der Bot verlangt von den Angemeldeten keine Zahlung.",
  "Imtihon pullik bo'lishi kerak bo'lsa — bekor qiling va \"Narx\" maydonini to'ldiring.": "Soll die Prüfung kostenpflichtig sein, brechen Sie ab und füllen Sie das Feld „Preis“ aus.",
  "Ha, bepul bo'lsin": "Ja, kostenlos",
  "Imtihon yangilandi": "Prüfung aktualisiert",
  "Imtihonni tahrirlash": "Prüfung bearbeiten",
  "Barcha maydonlarni o'zgartirish mumkin. Ishtirokchi bo'lsa, forma o'zgarishi ularning javoblariga ta'sir qilmaydi.": "Alle Felder können geändert werden. Gibt es bereits Teilnehmende, wirken sich Formularänderungen nicht auf deren Antworten aus.",
  "Bir nechta vaqt = botda tanlov. Birinchisi asosiy sana-vaqt.": "Mehrere Zeiten = Auswahl im Bot. Die erste ist der Haupttermin.",
  "Ro'yxatga olish muddati": "Anmeldeschluss",
  "Markaz o'quvchilariga chegirmali narx.": "Ermäßigter Preis für Teilnehmer des Zentrums.",
  "Taklif etiladigan darajalar": "Angebotene Niveaus",
  "Botda tugma sifatida chiqadi; foydalanuvchi bittasini tanlaydi.": "Erscheinen im Bot als Schaltflächen; die Person wählt eines.",
