  "Holat o'zgartirildi": "Status geändert",
  "PDF yaratildi, natijalar ishtirokchilarga yuborilmoqda": "PDF erstellt, die Ergebnisse werden an die Teilnehmenden gesendet",
  "PDF yaratishda xatolik": "Fehler beim Erstellen des PDF",
  "Imtihon o'chirildi": "Prüfung gelöscht",
  "Imtihon topilmadi": "Prüfung nicht gefunden",
  "Ulashish": "Teilen",
  "E'lon qilingan, lekin natijalar PDF'i yaratilmagan — yaratib, ishtirokchilarga yuborish": "Veröffentlicht, aber das Ergebnis-PDF fehlt — erstellen und an die Teilnehmenden senden",
  "PDF yaratib yuborish": "PDF erstellen und senden",
  "Natijalar PDFini yangi yorliqda ochish": "Ergebnis-PDF in neuem Tab öffnen",
  "Ishtirokchilar ({n})": "Teilnehmende ({n})",
  "Imtihonni o'chirish": "Prüfung löschen",
  "\"{title}\" imtihoni o'chiriladi. Ishtirokchilar va natijalar ham arxivlanadi (yo'qotilmaydi), ularning to'lov havolalari ishlamay qoladi. To'lagan ishtirokchi bo'lsa, avval ularni «Ishtirokchilar» bo'limidan pul qaytarilganini tasdiqlab o'chiring.": "Die Prüfung „{title}“ wird gelöscht. Teilnehmende und Ergebnisse werden ebenfalls archiviert (nicht verloren), ihre Zahlungslinks funktionieren nicht mehr. Gibt es zahlende Teilnehmende, löschen Sie diese zuerst im Tab „Teilnehmende“ und bestätigen Sie dabei die Rückzahlung.",
  "Baholash": "Bewertung",
  "Keyingi: {action}": "Weiter: {action}",
  "Yoki: {action}": "Oder: {action}",
  "Imtihon jarayoni yakunlandi.": "Die Prüfung ist abgeschlossen.",
  "Ro'yxatga olish havolasi": "Anmeldelink",
  "Ushbu havolani ulashing — foydalanuvchi havolaga bosib Telegram bot orqali \"{title}\" imtihoniga ro'yxatga olinadi.": "Teilen Sie diesen Link — wer darauf tippt, meldet sich über den Telegram-Bot zur Prüfung „{title}“ an.",
  "Imtihon holati \"Ro'yxat ochiq\" emas — havola ishlamaydi. Avval imtihonni \"Ro'yxat ochiq\" holatiga o'tkazing.": "Der Prüfungsstatus ist nicht „Anmeldung offen“ — der Link funktioniert nicht. Setzen Sie die Prüfung zuerst auf „Anmeldung offen“.",
  "QR kodni skanerlash orqali ham havolani ochish mumkin": "Der Link lässt sich auch über den QR-Code öffnen",
