  "Hozirgi holat:": "Aktueller Status:",
  "Holatni sahifa tepasidagi bosqichlar qatoridan o'zgartiring.": "Ändern Sie den Status über die Phasenleiste oben auf der Seite.",
  "Ishtirokchi": "Teilnehmende",
  "Qizil — bo'limning o'tish balidan past": "Rot — unter der Bestehensgrenze des Teils",
  "yashil — o'tish baliga yetgan": "grün — Bestehensgrenze erreicht",
  "Ballar saqlangach «O'rin» ustunini yuqoridagi tugma bilan qayta hisoblang.": "Berechnen Sie nach dem Speichern der Punkte die Spalte „Platz“ mit der Schaltfläche oben neu.",
